<?php
foreach(['APP_ENV'=>'testing','APP_CONFIG_CACHE'=>'/tmp/followup-test-cache.php','DB_CONNECTION'=>'sqlite','DB_DATABASE'=>':memory:','CACHE_STORE'=>'array','SESSION_DRIVER'=>'array','LOG_CHANNEL'=>'stderr'] as $k=>$v){putenv("$k=$v");$_ENV[$k]=$v;$_SERVER[$k]=$v;}
require dirname(__DIR__,2).'/vendor/autoload.php';$app=require dirname(__DIR__,2).'/bootstrap/app.php';$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
use Illuminate\Support\Facades\{DB,Schema};use App\Domain\Applications\RequestIdentity;use App\Models\WhatsappConversation;
if(DB::connection()->getDriverName()!=='sqlite'||config('database.connections.sqlite.database')!==':memory:')throw new RuntimeException('Unsafe DB');
Schema::create('applications',function($t){$t->id();$t->integer('customer_id');$t->integer('installment_request_id')->nullable();$t->dateTime('submitted_at')->nullable();});
Schema::create('form_links',function($t){$t->id();$t->integer('whatsapp_conversation_id');$t->integer('installment_request_id')->nullable();});
Schema::create('installment_requests',function($t){$t->id();$t->integer('whatsapp_conversation_id')->nullable();$t->string('applicant_phone')->nullable();$t->string('status');$t->softDeletes();});
Schema::create('whatsapp_messages',function($t){$t->id();$t->integer('whatsapp_conversation_id');$t->string('direction');$t->string('sender_type');$t->text('text')->nullable();$t->text('transcript')->nullable();});
$c=new WhatsappConversation(['phone'=>'201012345678:0','real_phone'=>null]);$c->id=7;$c->setRelation('customer',null);
$lookup=app(RequestIdentity::class);$tool=app(App\Agent\Tools\SendApplicationLinkTool::class);$guard=app(App\Agent\Runtime\ReplyGuard::class);
$n=0;$ok=function($v,$name)use(&$n){if(!$v)throw new RuntimeException($name);echo "PASS $name\n";$n++;};
$ok($tool->maySendLink($c),'first application allowed');
DB::table('installment_requests')->insert(['id'=>100,'applicant_phone'=>'01012345678','status'=>'pending']);
$ok($lookup->query(null,$c)->pluck('id')->all()===[100],'local phone matches international WhatsApp with device suffix');
$ok(!$tool->maySendLink($c),'pending request blocks another link');
DB::table('installment_requests')->where('id',100)->update(['applicant_phone'=>'+201012345678']);
$ok($tool->openRequest($c)?->id===100,'international stored phone also matches');
DB::table('installment_requests')->where('id',100)->update(['status'=>'rejected']);
$ok(!$tool->maySendLink($c),'rejected request does not automatically restart');
DB::table('whatsapp_messages')->insert(['whatsapp_conversation_id'=>7,'direction'=>'incoming','sender_type'=>'customer','text'=>'تمام شكرا']);
$ok(!$tool->maySendLink($c),'thanks does not cause another link');
DB::table('whatsapp_messages')->insert(['whatsapp_conversation_id'=>7,'direction'=>'outgoing','sender_type'=>'bot','text'=>'تم']);
DB::table('whatsapp_messages')->insert(['whatsapp_conversation_id'=>7,'direction'=>'incoming','sender_type'=>'customer','text'=>'عايز اقدم طلب جديد']);
$ok($tool->maySendLink($c),'explicit new application after terminal request allowed');
DB::table('installment_requests')->insert(['id'=>101,'applicant_phone'=>'01111111111','status'=>'pending']);
$ok($lookup->query(null,$c)->pluck('id')->all()===[100],'another customer request not exposed');
DB::table('form_links')->insert(['whatsapp_conversation_id'=>7,'installment_request_id'=>101]);
$ok($tool->openRequest($c)?->id===101,'form ownership finds request for another applicant');
$ok(!$tool->maySendLink($c),'open owned request overrides permission to reapply');
$ok((new ReflectionMethod($guard,'submissionHappened'))->invoke($guard,$c,[]),'legacy request counts as already submitted');
$blank=new WhatsappConversation(['phone'=>'not-a-phone']);$blank->id=8;$blank->setRelation('customer',null);
$ok(!$lookup->query(null,$blank)->exists(),'invalid or blank phone grants no access');
DB::table('whatsapp_messages')->insert(['whatsapp_conversation_id'=>8,'direction'=>'incoming','sender_type'=>'customer','text'=>'طلب برقم 4514']);
$ok(!$tool->maySendLink($blank),'unverified old request does not trigger fresh application');
DB::table('whatsapp_messages')->insert(['whatsapp_conversation_id'=>8,'direction'=>'outgoing','sender_type'=>'bot','text'=>'وضح رقم التقديم']);
DB::table('whatsapp_messages')->insert(['whatsapp_conversation_id'=>8,'direction'=>'incoming','sender_type'=>'customer','text'=>'تمام']);
$ok(!$tool->maySendLink($blank),'thanks after unverified request still does not trigger a new form');
config(['agent.eligibility.other_applicant'=>'dashboard alternative','agent.eligibility.no_work_hint'=>'dashboard employment rule','agent.installments.cap_explanation'=>'dashboard financing rule']);
$ok(App\Domain\Applications\OtherApplicant::line()==='dashboard alternative','alternative applicant wording from dashboard');
$ok(app(App\Domain\Installments\FinancingCapPolicy::class)->explanation(60000,null)==='dashboard financing rule','financing explanation from dashboard');
echo "$n passed\n";
